# DON'T overwrite pure column cells with horizontal fill
def smart_extend_to_nearest(input_grid):
    """Extend segments horizontally but don't overwrite pure columns"""
    pure_cols = {3: 6, 8: 8}

    output = [[0]*15 for _ in range(15)]

    # First, fill pure columns completely
    for j, color in pure_cols.items():
        for i in range(15):
            output[i][j] = color

    # Then fill rows (skip if cell already occupied by pure column)
    for i in range(15):
        indices = [(j, v) for j, v in enumerate(input_grid[i]) if v != 0]
        if not indices:
            continue

        vals_in_row = set(v for _,v in indices)

        if len(vals_in_row) == 1:
            primary_val = list(vals_in_row)[0]
            first_col = min(j for j,_ in indices)
            last_col = max(j for j,_ in indices)

            distance_to_3 = abs(first_col - 3)
            distance_to_8 = abs(first_col - 8)

            if distance_to_3 <= distance_to_8:
                end_target = 3
            else:
                end_target = 8

            for j in range(first_col, end_target + 1):
                # Don't overwrite pure column
                if j not in pure_cols or j != 8:  # Actually this is wrong logic
                    if j not in [3, 8]:  # Skip pure columns entirely
                        output[i][j] = primary_val
        else:
            for idx in indices:
                if idx[0] not in [3, 8]:
                    output[i][idx[0]] = idx[1]

    return output

print("Smart extend:")
for row in smart_extend_to_nearest(input_grid):
    print(row)

